mapper.update:
update inv_delivery_notice_detail
set delivered_qty = coalesce(delivered_qty, 0) + #{batchQty},
    delivered_cost_amount = coalesce(delivered_cost_amount, 0) + #{batchCost}
where detail_id = #{detailId}
  and coalesce(delivered_qty, 0) = #{expectedDeliveredQty}
  and notice_qty - coalesce(delivered_qty, 0) >= #{batchQty}
  and (delivered_cost_amount is not null
       or coalesce(delivered_qty, 0) = 0)
